import { debounce } from 'lodash-es';
import React, { useCallback, useState } from 'react';
import styled from 'styled-components';

import Colors from '@dynatrace/strato-design-tokens/colors';
import Spacings from '@dynatrace/strato-design-tokens/spacings';
import { MagnifyingGlassIcon } from '@dynatrace/strato-icons';

import { TextInput } from '../../../forms/text-input/TextInput.js';

const DEBOUNCE_TIME_MS = 300;

//#region Styled Components
const StyledMagnifyingGlassIcon = /* @__PURE__ */ styled(MagnifyingGlassIcon)({
  color: Colors.Icon.Neutral.Subdued,
});

const StyledTextInput = /* @__PURE__ */ styled(TextInput)({
  marginLeft: 'auto',
  width: '100%', // workaround for Windows issue
});

const StyledInputWrapper = /* @__PURE__ */ styled.div<{
  $mobileView: boolean;
}>(({ $mobileView }) => {
  return {
    minWidth: 230,
    marginLeft: 'auto',
    marginBottom: $mobileView ? Spacings.Size12 : 0,
    width: $mobileView ? '100%' : 'auto',
    order: $mobileView ? 1 : 0,
  };
});
//#end region Styled Components

/**
 * Intended for filtering column visibility checkboxes. Input is debounced.
 *
 * @param props - value, onChange and placeholder
 * @returns SearchInput for filtering column visibility checkboxes.
 */
export function SearchInput(props: {
  value: string;
  placeholder: string;
  onChange?: (value: string) => void;
  mobileView: boolean;
}): React.ReactElement {
  const { value, placeholder, onChange, mobileView } = props;
  const [filterValue, setFilterValue] = useState(value);

  // eslint-disable-next-line react-hooks/exhaustive-deps
  const updateFilterDebounced = useCallback(
    debounce((value) => {
      onChange && onChange(value);
    }, DEBOUNCE_TIME_MS),
    [onChange],
  );
  const onChangeInternal = (value: string) => {
    setFilterValue(value);
    updateFilterDebounced(value);
  };

  return (
    <StyledInputWrapper $mobileView={mobileView}>
      <StyledTextInput
        placeholder={placeholder}
        value={filterValue}
        onChange={onChangeInternal}
      >
        <TextInput.Prefix>
          <StyledMagnifyingGlassIcon />
        </TextInput.Prefix>
      </StyledTextInput>
    </StyledInputWrapper>
  );
}
